/**
 * @module types
 * Shared domain types for Nivisok.
 */

/**
 * Represents a single saved note.
 *
 * - Notes created via the context menu (text selection) carry the page URL.
 * - Notes typed directly into the side panel always have `url: null` and are
 *   displayed with a "Self created" label.
 */
export interface INote {
  /** UUID v4 generated by `crypto.randomUUID()`. */
  id: string;

  /** The raw text content of the note. */
  content: string;

  /**
   * The URL of the page from which the note was clipped via context menu.
   * Always `null` for notes created by typing in the side panel.
   */
  url: string | null;

  /** Unix timestamp (ms) of when the note was first created. */
  createdAt: number;

  /**
   * Unix timestamp (ms) of the most recent edit.
   * Absent on notes that have never been edited.
   */
  updatedAt?: number;
}
